/** \brief AUTOSAR module patch version */
//#define DIO_SW_PATCH_VERSION  27U

/**
 * Macro for checking the consistency of AUTOSAR Spec versions of the
 * different files of the DIO module
 */
#define DIO_AR_VERSION_CHECK(                                                  \
    file_ar_major_version,                                             \
    file_ar_minor_version,                                             \
    file_ar_revision_version                                           \
    )                                                                          \
    (                                                                          \
        ((DIO_AR_RELEASE_MAJOR_VERSION) == (4u)) && \
        ((DIO_AR_RELEASE_MINOR_VERSION) == (0u)) && \
        ((DIO_AR_RELEASE_REVISION_VERSION) == (3u)) \
    )/* MISRA-1 *//* PRQA S 3453 1 *//* Implementation often uses macro like function. */

/**
 * Macro for checking the consistency of the software versions of the
 * different files of the Dio module
 */
#define DIO_SW_VERSION_CHECK(                                  \
    file_sw_major_version,                                     \
    file_sw_minor_version,                                     \
    file_sw_patch_version                                      \
    )                                                          \
    (                                                          \
        ((DIO_SW_MAJOR_VERSION) == (1U)) && \
        ((DIO_SW_MINOR_VERSION) == (0U)) && \
        ((DIO_SW_PATCH_VERSION) >= (27U))    \
    )/* MISRA-1 *//* PRQA S 3453 *//* Implementation often uses macro like function. */

/**
 * Macro for checking the consistency of the software versions dependend
 * modules of Dio module
 * \pre: ar_major_def and ar_minor_def needs to be defined
 */

#define DIO_AR_DEPENDEND_CHECK(                \
    ar_major_def,ar_minor_def,                 \
    ar_major_need,ar_minor_need                \
    )                                          \
    (                                          \
        ((ar_major_def) == (ar_major_need)) && \
        ((ar_minor_def) == (ar_minor_need))    \
    )/* MISRA-1 *//* PRQA S 3453 *//* Implementation often uses macro like function. */
    
#define DIO_EXTRA_CHECK_INSTANCE(instance_id)  \
        (                                      \
          ((DIO_INSTANCE_ID) == (instance_id)) \
        )/* MISRA-1 *//* PRQA S 3453 *//* Implementation often uses macro like function. */


#define DIO_EXTRA_CHECK(                      \
    module_id,vendor_id, instance_id          \
    )                                         \
    (                                         \
        ((DIO_MODULE_ID) == (120U)) &&   \
        ((DIO_VENDOR_ID) == (66U)) &&   \
        ((DIO_INSTANCE_ID) == (0U))  \
    )/* MISRA-1 *//* PRQA S 3453 *//* Implementation often uses macro like function. */

